<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Activator { public static function activate(): void { if ( version_compare( get_bloginfo( 'version' ), '6.5', '<' ) ) wp_die( esc_html__( 'Cyberfort AI Register requires WordPress 6.5 or later.', 'cyberfort-ai-register' ) ); foreach ( [ 'cfair_server_url' => '', 'cfair_environment' => 'production', 'cfair_api_version' => 'v1', 'cfair_language' => 'auto', 'cfair_cache_duration' => 900, 'cfair_stale_retention' => 604800, 'cfair_base_slug' => 'ai-register', 'cfair_delete_data' => 0 ] as $key => $value ) add_option( $key, $value, '', false ); add_option( 'cfair_api_key', '', '', false ); add_option( 'cfair_schema_version', '1', '', false ); ( new Routes() )->register_rules(); flush_rewrite_rules(); set_transient( 'cfair_activation_notice', 1, DAY_IN_SECONDS ); } }
